</body></html>
'@
Set-Content app\index.html $ix -Encoding UTF8

# sw.js v11 network-first + limpeza agressiva de caches antigos
$sw=@'
const CACHE='mb-app-v11';
self.addEventListener('install',function(e){self.skipWaiting()});
self.addEventListener('activate',function(e){e.waitUntil(caches.keys().then(function(ks){return Promise.all(ks.map(function(k){return caches.delete(k)}))}).then(function(){return self.clients.claim()}))});
self.addEventListener('fetch',function(e){
  var u=new URL(e.request.url);
  if(u.pathname.indexOf('/api/')>=0)return;
  if(e.request.method!=='GET')return;
  if(u.origin!==location.origin)return;
  e.respondWith(fetch(e.request).then(function(r){var cp=r.clone();caches.open(CACHE).then(function(c){c.put(e.request,cp).catch(function(){})});return r}).catch(function(){return caches.match(e.request).then(function(h){return h||caches.match('./index.html')})}));
});
'@
Set-Content app\sw.js $sw -Encoding UTF8

# apagar lixos .ps1 velhos
Remove-Item AUDITORIA-FINAL.ps1,CORRECAO-3.ps1,FINAL-FIX.ps1,MELHORIAS-1.ps1,REVISAO-FINAL.ps1,SECRETO-1.ps1,SUGESTOES-2.ps1,SUGESTOES-3.ps1,VOTO-SECRETO-FIX.ps1,FIX-ULTIMO.ps1,FIX-FINAL.ps1 -ErrorAction SilentlyContinue

# commit + push silencioso
git add app/ | Out-Null
git commit -m "fix: app.js reescrito do zero (sintaxe valida, todas features preservadas)" | Out-Null
git push origin master | Out-Null
Write-Host "PUSH OK" -ForegroundColor Green

# teste ao vivo (3 tentativas)
$ok=$false
for($t=1;$t -le 3;$t++){
  Start-Sleep 50
  try{
    $r=Invoke-WebRequest 'https://raw.githubusercontent.com/xbrancox/mudabrasil/master/app/app.js' -UseBasicParsing -TimeoutSec 20
    $c=$r.Content
    $checks=@('VOTO SECRETO','GLOSS','renderDiaD','modalCedula','telaLogin','participacaoHTML','vibrate','sistema no ar','data-fix','comparar','flushFila','VOTA=','function render()')
    $todosOK=$true
    foreach($ch in $checks){ if(-not $c.Contains($ch)){ $todosOK=$false; break } }
    if($todosOK -and $c.Length -gt 30000){ Write-Host "TENTATIVA $t : TUDO NO AR" -ForegroundColor Green; $ok=$true; break }
    else { Write-Host "TENTATIVA $t : aguardando cache..." -ForegroundColor Yellow }
  }catch{ Write-Host "TENTATIVA $t : rede oscilou" -ForegroundColor Yellow }
}
if($ok){ Write-Host "FECHADO. Abra o app no celular 2x (limpa SW)." -ForegroundColor Cyan }
else { Write-Host "AINDA PENDENTE - rode de novo em 3 minutos ou me mande print." -ForegroundColor Yellow }
Read-Host "Enter"